using Arconist.Core;
using System.Text.Json;
using System.Security.Cryptography;
string root=args.Length>0?args[0]:".",output=args.Length>1?args[1]:"linked-evidence";Directory.CreateDirectory(output);
int passed=0,failed=0;var outcomes=new List<object>();
void Check(bool ok,string why){if(!ok)throw new Exception(why);}
void Test(string name,Action body){try{body();passed++;outcomes.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});Console.WriteLine("FAIL "+name+": "+e.Message);}}
string Load(string n)=>File.ReadAllText(Path.Combine(root,"reconstructed/godot/content",n));
string Aff(string body)=>"AudioOffset:0\nTimingPointDensityFactor:1.0\n-\ntiming(0,120.00,4.00);\n"+body;
const string first="arc(1000,2001,0.50,0.50,s,0.50,0.50,0,none,false);";
const string next="arc(2001,3001,0.50,0.50,s,0.50,0.50,0,none,false);";
Kernel New(int height=0,string? text=null){var k=new Kernel(Chart.Parse(text??Load("native_linked_arc_successors.aff")),arcHeight:height);k.Frame(0);k.Frame(3002);return k;}
void F(Kernel k,int e)=>k.Frame(e+3002);
SkyContact At(Kernel k)=>new(new SkyPoint(0,k.Arcs[0].Geometry.Y0,0));
void Begin(Kernel k){F(k,1000);k.DownSpatial(4002,42,0,At(k));}
Test("exact E038 original fixture SHA and content",()=>{byte[] bytes=File.ReadAllBytes(Path.Combine(root,"research_harness/fixtures/native_linked_arc_successors.aff"));Check(Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant()=="c0abe4ca157ea34888c27571081383284df5b7ca61e58cce3815ac41ecedd527"&&bytes.SequenceEqual(File.ReadAllBytes(Path.Combine(root,"reconstructed/godot/content/native_linked_arc_successors.aff"))),"fixture identity");});
Test("typed root successor and shared group/color identities",()=>{var k=New();var a=k.Arcs[0];var b=k.Arcs[1];Check(a.Id!=b.Id&&ReferenceEquals(a.Successors.Single(),b)&&ReferenceEquals(b.Predecessor,a)&&a.Predecessor==null&&b.Successors.Count==0,"runtime links");Check(ReferenceEquals(a.Color,b.Color)&&ReferenceEquals(a.Group,b.Group)&&!ReferenceEquals((object)a.Color,a.Group)&&k.ArcGroups.Count==1,"separate color/group");Check(ReferenceEquals(a.Data.Successors.Single(),b.Data)&&ReferenceEquals(b.Data.Predecessor,a.Data)&&ReferenceEquals(a.Data.Group,b.Data.Group),"parsed links");});
Test("factory0 linker1 provenance before record generation",()=>{var k=New();Check(k.Arcs.Select(a=>a.Data.GenerationFlag).SequenceEqual(new[]{0,1})&&k.Arcs.Select(a=>a.Data.GeneratedWithFlag).SequenceEqual(new[]{0,1})&&k.Arcs.All(a=>a.Data.RecordsGenerated),"flags/order");Check(k.Arcs[0].Data.BaseRecords.Select(r=>r.Time).SequenceEqual(new[]{1250,1500,1750})&&k.Arcs[1].Data.BaseRecords.Select(r=>r.Time).SequenceEqual(new[]{2001,2251,2501,2751}),"actual generation not hardcoded final arrays");});
Test("folded six records seven units and natural chart end",()=>{var k=New();Check(k.Arcs[0].Records.Select(r=>(r.Time,r.Weight)).SequenceEqual(new[]{(1250,1),(1500,2)})&&k.Arcs[1].Records.Select(r=>(r.Time,r.Weight)).SequenceEqual(new[]{(2001,1),(2251,1),(2501,1),(2751,1)}),"records");Check(k.Arcs[0].Data.Folded&&!k.Arcs[1].Data.Folded&&k.Chart.JudgmentUnits==7&&k.Chart.EndTime==3501,"natural N7 not prepared N8");});
Test("geometry H0 native depths and distinct H500",()=>{var k=New();Check(k.Arcs.Select(a=>a.Geometry.Z).SequenceEqual(new[]{-8097,-8089})&&k.Arcs.All(a=>a.Geometry.Samples.Count==9&&a.Geometry.Y0==50),"E038 geometry");Check(New(500).Arcs.All(a=>a.Geometry.Y0==300),"Godot environment");});
Test("successor active-range membership before cache eligibility",()=>{var k=New();F(k,1000);Check(k.Arcs.All(a=>a.Active)&&k.Arcs[0].CacheEnabled&&!k.Arcs[1].CacheEnabled&&k.Pure==0,"admission versus spatial eligibility");});
Test("DOWN does not activate claim or manufacture a frame",()=>{var k=New();Begin(k);Check(k.Arcs.All(a=>!a.Holding)&&k.Arcs[0].Color.Owner==-1&&k.ClaimedIds.Count==0&&k.LastFrameTime==1000,"DOWN boundary");F(k,1001);Check(k.Arcs[0].Holding&&!k.Arcs[1].Holding&&k.Arcs[0].Color.Owner==0,"first continuous activation");});
Test("E038 complete intermediate frame recorder owner group trace",()=>{
 var k=New();using var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,"reference_traces/r009/native-linked.json")));var rows=doc.RootElement.GetProperty("frames").EnumerateArray().ToArray();var expected=doc.RootElement.GetProperty("callbacks").EnumerateArray().ToArray();var trace=new List<object>();var callbacks=new List<RecorderObservation>();string? divergence=null;
 try{Begin(k);foreach(var row in rows){int e=row.GetProperty("e").GetInt32();if(e!=1000)F(k,e);var a=k.Arcs[0];var b=k.Arcs[1];var g=k.ArcGroups[0];callbacks.AddRange(k.RecorderTrace);trace.Add(new{e,root=new{a.Active,a.Holding,a.CacheEnabled,a.Depth,a.ResolutionWrites},next=new{b.Active,b.Holding,b.CacheEnabled,b.Depth,b.ResolutionWrites},owner=a.Color.Owner,a.Color.ReleaseTime,a.Color.PreviouslyClaimed,claimed=k.ClaimedIds,group=new{g.Active,g.CacheRelated,g.Accepted,g.Window,g.TimestampHistory},k.Pure,k.Score,health=(double)k.Health,k.RecorderCalls,rootScan=a.LastLinkScan,nextScan=b.LastLinkScan});Check(a.Holding==row.GetProperty("root").GetBoolean()&&b.Holding==row.GetProperty("next").GetBoolean()&&k.Pure==row.GetProperty("pure").GetInt32()&&(double)k.Health==row.GetProperty("health").GetDouble(),$"E{e} first activity/counter/health difference");Check(k.Contacts.Single().Id==0&&k.ContactCount==1,"same retained contact");if(e>1000)Check(a.Color.Owner==0&&a.Color.ReleaseTime==-1&&a.Color.PreviouslyClaimed&&k.ClaimedIds.SequenceEqual(new[]{0})&&g.Active&&g.Accepted&&g.CacheRelated,"shared owner/group");if(e==2000)Check(a.LastLinkScan!.OwnRecord==null&&a.LastLinkScan.SuccessorRecord==2001,"root consumes successor lookup");if(e==2001)Check(b.LastLinkScan!.Predecessor==a.Id&&b.LastLinkScan.OwnRecord==2001&&a.Active,"successor reads predecessor and own pending record");if(e==2002)Check(!a.Active&&a.SuccessorCleanupPreserved,"successor-aware cleanup");}
 Check(callbacks.Count==7&&k.RecorderCalls==7,"seven genuine callbacks");for(int i=0;i<7;i++){var c=callbacks[i];var r=expected[i];Check(c.Sequence==i+1&&c.EffectiveTime==r.GetProperty("e").GetInt32()&&c.Checkpoint==r.GetProperty("time").GetInt32()&&c.Pure==r.GetProperty("pure").GetInt32()&&c.Score==r.GetProperty("score").GetInt32()&&(double)c.Health==r.GetProperty("health").GetDouble()&&c.Combo==i+1&&c.Shining==i+1,"callback "+i);}
 Check(k.Arcs.Sum(a=>a.ResolutionWrites)==6&&k.Arcs.SelectMany(a=>a.Records).All(r=>r.Resolved)&&k.Far==0&&k.Lost==0&&k.Score==10000007,"six guards seven units");k.Up(42);Check(k.ContactCount==0&&k.ClaimedIds.Count==0&&k.Arcs[1].Color.Owner==-1&&k.Arcs[1].Color.ReleaseTime==2876&&k.Arcs[1].Holding,"genuine UP leaves prior-frame activity");F(k,2877);var group=k.ArcGroups[0];Check(!k.Arcs[1].Holding&&!group.Active&&group.CacheRelated&&!group.Accepted&&k.Arcs[1].Color.PreviouslyClaimed&&k.Result==null,"native cleanup boundary/cache byte");}
 catch(Exception e){divergence=e.Message;throw;}
 finally{File.WriteAllText(Path.Combine(output,"E038-linked.json"),JsonSerializer.Serialize(new{authority="E038",firstDifference=divergence,trace,callbacks,nativeCompletion=false},new JsonSerializerOptions{WriteIndented=true}));}
});
Test("weight2 produces two independent score/gauge operations once",()=>{var k=New();Begin(k);F(k,1125);F(k,1375);Check(k.Judgments.Count==2&&k.RecorderTrace.Count==2&&k.RecorderTrace[0].Pure==2&&(double)k.RecorderTrace[0].Health==23.257143020629883&&k.RecorderTrace[1].Pure==3&&(double)k.RecorderTrace[1].Health==34.88571548461914&&k.Arcs[0].ResolutionWrites==2,"separate float32 updates/one guard");F(k,1375);Check(k.RecorderTrace.Count==0&&k.RecorderCalls==3&&k.Arcs[0].ResolutionWrites==2,"repeat guard");});
Test("junction has exclusive cache/activity and no new DOWN",()=>{var k=New();Begin(k);F(k,1001);F(k,2000);Check(k.Arcs[0].Holding&&!k.Arcs[1].Holding,"before");F(k,2001);Check(!k.Arcs[0].CacheEnabled&&!k.Arcs[0].Holding&&k.Arcs[1].Holding&&k.Arcs[1].CacheEnabled&&k.Contacts.Single().Id==0,"exact junction");F(k,2002);Check(!k.Arcs[0].Active&&k.Arcs[1].Holding&&k.Arcs[0].Color.Owner==0,"after");});
Test("foreign contact cannot replace shared owner",()=>{var k=New();Begin(k);F(k,1001);k.DownSpatial(4003,43,0,At(k));k.MoveSpatial(42,0,new SkyContact(new SkyPoint(9000,100,0)));F(k,2001);Check(k.Arcs.All(a=>!a.Holding)&&k.Arcs[0].Color.Owner==0&&k.Contacts.Count==2&&!k.ArcGroups[0].Active,"no stealing");});
Test("release before successor cannot leave stale support",()=>{var k=New();Begin(k);F(k,1375);F(k,2000);k.Up(42);F(k,2001);Check(!k.Arcs[1].Holding&&k.Arcs[1].Color.Owner==-1&&k.ContactCount==0&&k.Pure==3,"no phantom contact");F(k,3502);Check(k.Result!.Pure==3&&k.Result.Lost==4&&k.RecorderCalls==7,"reconstructed missed successor");});
Test("reacquisition obeys inherited release gate across successor",()=>{var k=New();Begin(k);F(k,1375);F(k,2000);k.Up(42);k.DownSpatial(5002,43,0,At(k));F(k,2999);Check(!k.Arcs[1].Holding&&k.Arcs[1].Color.Owner==-1,"below gate");F(k,3000);Check(k.Arcs[1].Holding&&k.Arcs[1].Color.Owner==1,"equality reacquires, engineering schedule");});
Test("weighted missed record costs two separate damage operations",()=>{var k=New();Begin(k);F(k,1125);F(k,1200);k.Up(42);F(k,2000);Check(k.RecorderTrace.Count==2&&k.Lost==2&&k.RecorderTrace[0].Health==k.BaseGain-2f&&k.RecorderTrace[1].Health==(k.BaseGain-2f)-2f&&k.Arcs[0].ResolutionWrites==2,"separate LOST recorder loops");F(k,2250);Check(k.Lost==2&&k.Arcs[0].Records.All(r=>r.Time!=1750),"removed1750 never missed");});
Test("completed N7 result is reconstructed integration",()=>{var k=New();Begin(k);foreach(int e in new[]{1001,1125,1375,2001,2126,2376,2626,2876})F(k,e);k.Up(42);F(k,3502);Check(k.Result!.Score==10000007&&k.Result.Pure==7&&k.Result.Shining==7&&k.Result.MaxCombo==7&&k.Result.Lost==0&&k.Result.Health==81&&k.Result.Category==3,"complete reconstructed result");});
Test("extended visible practice derives its own N31 and 30 guards",()=>{var k=New(500,Load("linked_practice.aff"));Check(k.Chart.JudgmentUnits==31&&k.Chart.EndTime==12501&&k.Arcs.Sum(a=>a.Records.Count)==30,"practice identity distinct from E038");for(int e=1;e<=12502;e++){F(k,e);if(e==4000)k.DownSpatial(e+3002,42,0,At(k));if(e==12000)k.Up(42);}Check(k.Result!.Score==10000031&&k.Pure==31&&k.Lost==0&&k.Arcs.Sum(a=>a.ResolutionWrites)==30,"full practice");});
foreach(int pauseAt in new[]{900,1200,2000,2001,2002}){int p=pauseAt;Test("pause60seconds atE"+p+" preserves chain progression",()=>{var k=New();int delay=0;for(int e=1;e<=3502;e++){k.Frame(e+3002+delay);if(e==1000)k.DownSpatial(e+3002+delay,42,0,At(k));if(e==p){var before=k.Arcs.Select(a=>(a.Cache.X,a.Cache.Y,a.CacheEnabled,a.Depth)).ToArray();int pure=k.Pure;int owner=k.Arcs[0].Color.Owner;k.Pause(e+3002+delay);k.Frame(e+63002+delay);Check(k.Timeline.EffectiveTime==e&&k.Pure==pure&&k.Arcs[0].Color.Owner==owner&&k.Arcs.Select(a=>(a.Cache.X,a.Cache.Y,a.CacheEnabled,a.Depth)).SequenceEqual(before),"frozen");Check(k.Resume(e+63002+delay),"resume");delay+=60000;}}Check(k.Result!.Pure==7&&k.Lost==0&&k.Score==10000007,"equivalent effective schedule");});}
Test("paused UP and CANCEL clear shared contact without resetting history",()=>{foreach(bool cancel in new[]{false,true}){var k=New();Begin(k);F(k,1125);k.Pause(4202);if(cancel)k.Cancel(42);else k.Up(42);k.Frame(64202);Check(k.ContactCount==0&&k.ClaimedIds.Count==0&&k.Arcs[0].Color.Owner==-1,"cleanup");k.Resume(64202);k.Frame(65003);Check(k.Arcs.All(a=>!a.Holding),"no stale support");}});
Test("new sessions reset group cache links guards and owner",()=>{var old=New();Begin(old);F(old,2626);var fresh=New();Check(!ReferenceEquals(old.ArcGroups[0],fresh.ArcGroups[0])&&fresh.Arcs[0].Color.Owner==-1&&fresh.RecorderCalls==0&&fresh.Arcs.All(a=>a.ResolutionWrites==0)&&!fresh.ArcGroups[0].Active,"fresh state");});
Test("group empty timestamps and unsupported window explicitly retained",()=>{var k=New();Begin(k);F(k,2000);Check(k.ArcGroups[0].TimestampHistory.Count==0&&k.ArcGroups[0].Window==0&&k.ArcGroups[0].WindowBehavior=="UNSUPPORTED_NONEMPTY_TIMESTAMP_HISTORY","bounded group behavior");});
Test("ambiguous branching triple tolerance trace color timing layouts reject",()=>{var invalid=new[]{first+next+"arc(3001,4001,0.50,0.50,s,0.50,0.50,0,none,false);",first+next+next,first+next+"arc(3001,1000,0.50,0.50,s,0.50,0.50,0,none,false);",first+next.Replace("2001,3001","2002,3002"),first+next.Replace("0.50,0.50,s","0.51,0.51,s"),first+next.Replace(",0,none",",1,none"),first+next.Replace("false)","true)[arctap(2501)]"),next+first,first+next+"timing(2001,120.00,4.00);",first+next.Replace("0.50,0.50,s","0.50,0.80,s")};foreach(var body in invalid){bool rejected=false;try{Chart.Parse(Aff(body));}catch(NotSupportedException){rejected=true;}Check(rejected,body);}});
File.WriteAllText(Path.Combine(output,"linked-core-tests.json"),JsonSerializer.Serialize(new{passed,failed,skipped=0,outcomes},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"R009 core: {passed+failed}; passed:{passed}; failed:{failed}; skipped:0");return failed==0?0:1;
